# -*- coding: utf-8 -*-
"""Writes Editor/LanbaiPoemMaterials.cs from the solved fills (called by build_fonts.py; verify r2 B.1).
The C# is a template with one generated table; do not hand-edit the .cs, edit this file or lanbai_color.py."""
import os

HERE = os.path.dirname(os.path.abspath(__file__))
KIT = os.path.normpath(os.path.join(HERE, '..'))

TEMPLATE = r'''// Lanbai / 蓝白 — per-poem TMP material presets and the two scrim materials, with the SOLVED fill colours.
// GENERATED by Tools~/gen_poem_materials.py (via build_fonts.py) — do not edit; edit Tools~/lanbai_color.py.
//
// ⚠ UNCOMPILED IN UNITY. Type-checked outside Unity with Roslyn (Tools~/compile_check) only.
//
// Why (art bible law 1 + verify round 2, B.1): the §7.5 poem colours are SCREEN targets. A poem is unlit and is graded
// by its scene's PPv2 profile, and TMP 3.0.x applies no colour-space conversion to vertex colours
// (TMP_SDF.shader: faceColor.rgb *= input.color.rgb). So TMP Vertex Color stays WHITE (alpha only) and the colour
// lives on a per-poem copy of the font asset's material as the HDR _FaceColor = the scene-linear fill solved through
// that scene's grade. The scrims work the same way: SpriteRenderer.color = (1, 1, 1, alpha), the fill is the
// Sprites/Default material's _Color.
//
// Menu 蓝白/Fonts/Build Poem Materials, or call LanbaiPoemMaterials.BuildAll() (returns a report string).
// Needs the font assets first (LanbaiTMPFontBuilder.BuildAll). Output: <kit>/FontAssets/PoemMaterials/*.mat.
// Re-running updates the materials in place (GUIDs kept). A TMP preset is a copy of the font asset's material (same
// atlas), named "<font asset> - <poem id>", so it also appears in the TextMeshPro component's Material Preset list.
//
// PRESETS ARE INITIAL VALUES, NEVER ANIMATED (verify round 3, m4): a main line and its mirror share one preset but
// animate _OutlineSoftness differently (0.9 -> 0 vs 0.9 -> 0.3), and Face Dilate is set per material (desktop 0.05,
// VR 0.10). So: assign the preset to tmp.fontSharedMaterial once, then animate tmp.fontMaterial — TMP instantiates
// a private copy per object on first access. The scrim materials are shared; their fades go on SpriteRenderer.color.a.
//
// Two poems are read during a PPv2 volume blend and are solved at the blend weight of mid-hold: P03 李白 I under
// S3 at weight 0.30 over S2, P04a 里尔克 under S4 at weight 0.195 over S3 (the "Profile" column shows the blend).
#if UNITY_EDITOR
using System;
using System.Text;
using TMPro;
using UnityEditor;
using UnityEngine;

namespace Lanbai.Fonts.EditorTools
{
    public static class LanbaiPoemMaterials
    {
        struct Entry
        {
            public string Name, Kind, TmpAsset, Profile, Target, FillHdr;
            public float R, G, B;
            public Entry(string name, string kind, string tmpAsset, string profile, string target, string fillHdr, float r, float g, float b)
            {
                Name = name; Kind = kind; TmpAsset = tmpAsset; Profile = profile; Target = target; FillHdr = fillHdr;
                R = r; G = g; B = b;
            }
        }

        public const int ScrimRenderQueue = 3009;   // glass 3000 < scrim 3009 < poem 3010 (README §4.5)
        public const int PoemRenderQueue = 3010;

        // ---- generated: name, kind, TMP font asset (tmp_face only), profile, screen target, HDR picker value, LINEAR fill
        static readonly Entry[] Entries =
        {
@@ENTRIES@@
        };
        // ---- end generated

        [MenuItem("蓝白/Fonts/Build Poem Materials (solved fills)")]
        static void MenuBuild() { Debug.Log(BuildAll()); }

        /// <summary>Creates / updates every poem preset and both scrim materials. Returns a report.</summary>
        public static string BuildAll()
        {
            string kit = KitRoot();
            if (kit == null) return "LanbaiPoemMaterials: kit folder not found (the script must stay at <kit>/Editor/LanbaiPoemMaterials.cs).";
            var sb = new StringBuilder();
            bool linear = PlayerSettings.colorSpace == ColorSpace.Linear;
            sb.AppendLine("Lanbai poem materials — kit " + kit + ", colour space " + PlayerSettings.colorSpace);
            if (!linear)
                sb.AppendLine("  WARNING: the project is not in Linear colour space. VRChat worlds are Linear; every fill here is a linear value "
                              + "solved for the Linear pipeline, so the colours will be wrong until Player Settings > Color Space = Linear.");
            string outDir = kit + "/FontAssets/PoemMaterials";
            if (!AssetDatabase.IsValidFolder(kit + "/FontAssets")) AssetDatabase.CreateFolder(kit, "FontAssets");
            if (!AssetDatabase.IsValidFolder(outDir)) AssetDatabase.CreateFolder(kit + "/FontAssets", "PoemMaterials");

            int ok = 0, fail = 0;
            foreach (Entry e in Entries)
            {
                try
                {
                    string line = e.Kind == "scrim" ? BuildScrim(outDir, e, linear) : BuildPreset(kit, outDir, e, linear);
                    if (line.StartsWith("  OK", StringComparison.Ordinal)) ok++; else fail++;
                    sb.AppendLine(line);
                }
                catch (Exception ex) { fail++; sb.AppendLine("  FAIL " + e.Name + ": " + ex.GetType().Name + " " + ex.Message); }
            }
            AssetDatabase.SaveAssets();
            sb.AppendLine(fail == 0 ? "POEM MATERIALS PASS (" + ok + ")" : "POEM MATERIALS: " + ok + " ok, " + fail + " not built");
            return sb.ToString();
        }

        static string BuildPreset(string kit, string outDir, Entry e, bool linear)
        {
            string faPath = kit + "/FontAssets/" + e.TmpAsset + ".asset";
            TMP_FontAsset fa = AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(faPath);
            if (fa == null || fa.material == null)
                return "  SKIP " + e.Name + ": font asset " + faPath + " not found (run 蓝白/Fonts/Build TMP Font Assets first)";
            string path = outDir + "/" + e.Name + ".mat";
            Material m = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (m == null)
            {
                m = new Material(fa.material);        // same shader, same atlas (_MainTex), same SDF ratios
                m.name = e.Name;
                AssetDatabase.CreateAsset(m, path);
            }
            else
            {
                m.shader = fa.material.shader;
                m.CopyPropertiesFromMaterial(fa.material);   // picks up a rebuilt atlas; the colour is written again below
            }
            m.renderQueue = PoemRenderQueue;
            SetLinearColor(m, "_FaceColor", new Color(e.R, e.G, e.B, 1f), linear);
            EditorUtility.SetDirty(m);
            return Report(m, "_FaceColor", e, linear);
        }

        static string BuildScrim(string outDir, Entry e, bool linear)
        {
            Shader sh = Shader.Find("Sprites/Default");
            if (sh == null) return "  FAIL " + e.Name + ": shader Sprites/Default not found";
            string path = outDir + "/" + e.Name + ".mat";
            Material m = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (m == null)
            {
                m = new Material(sh);
                m.name = e.Name;
                AssetDatabase.CreateAsset(m, path);
            }
            else if (m.shader != sh) m.shader = sh;
            m.renderQueue = ScrimRenderQueue;
            SetLinearColor(m, "_Color", new Color(e.R, e.G, e.B, 1f), linear);   // the alpha lives on SpriteRenderer.color
            EditorUtility.SetDirty(m);
            return Report(m, "_Color", e, linear);
        }

        /// <summary>
        /// Material.SetColor takes a gamma-space colour; in a Linear project Unity converts it with GammaToLinearSpace
        /// (sRGB curve below 1, pow 2.2 above) before the shader sees it. Color.gamma is the exact inverse
        /// (LinearToGammaSpace), so SetColor(linear.gamma) delivers the linear fill, HDR values above 1 included.
        /// </summary>
        static void SetLinearColor(Material m, string prop, Color lin, bool linear)
        {
            m.SetColor(prop, linear ? lin.gamma : lin);
        }

        static string Report(Material m, string prop, Entry e, bool linear)
        {
            Color stored = m.GetColor(prop);
            Color back = linear ? stored.linear : stored;
            float err = Mathf.Max(Mathf.Abs(back.r - e.R) / Mathf.Max(e.R, 1e-4f),
                        Mathf.Max(Mathf.Abs(back.g - e.G) / Mathf.Max(e.G, 1e-4f), Mathf.Abs(back.b - e.B) / Mathf.Max(e.B, 1e-4f)));
            return string.Format("  {0} {1}  [{2}] {3} target {4} -> {5} = linear ({6:0.0000}, {7:0.0000}, {8:0.0000}), queue {9}{10}",
                err < 0.002f ? "OK  " : "DIFF", e.Name, e.Profile, prop, e.Target, e.FillHdr, back.r, back.g, back.b, m.renderQueue,
                err < 0.002f ? "" : "  (read-back differs by " + (err * 100f).ToString("0.00") + " %)");
        }

        static string KitRoot()
        {
            const string tail = "/Editor/LanbaiPoemMaterials.cs";
            foreach (string g in AssetDatabase.FindAssets("LanbaiPoemMaterials t:MonoScript"))
            {
                string p = AssetDatabase.GUIDToAssetPath(g);
                if (p.EndsWith(tail, StringComparison.Ordinal)) return p.Substring(0, p.Length - tail.Length);
            }
            return null;
        }
    }
}
#endif
'''


def cs_str(s):
    return '"' + s.replace('\\', '\\\\').replace('"', '\\"') + '"'


def write(materials):
    rows = []
    for m in materials:
        r, g, b = m['fill_linear']
        rows.append('            new Entry(%s, %s, %s, %s, %s, %s, %sf, %sf, %sf),' % (
            cs_str(m['name']), cs_str(m['kind']), cs_str(m.get('tmp_asset', '')), cs_str(m['profile']),
            cs_str(m['target']), cs_str(m['fill_hdr']), repr(round(float(r), 5)), repr(round(float(g), 5)), repr(round(float(b), 5))))
    src = TEMPLATE.replace('@@ENTRIES@@', '\n'.join(rows))
    path = os.path.join(KIT, 'Editor', 'LanbaiPoemMaterials.cs')
    with open(path, 'w', encoding='utf-8', newline='\n') as f:
        f.write(src)
    return path
